    'onp.d1-time': '01',
    'onp.d1-label': 'Rechte pr&uuml;fen',
    'onp.d1-text': 'Was bringt die Plattform wirklich? Publikum, Rechte, Assets und Preis &ndash; bewertet, bevor jemand unterschreibt.',
    'onp.d2-time': '02',
