(function () {
  var STORAGE_KEY = 'sj_lang';

  function getCurrentLang() {
    return localStorage.getItem(STORAGE_KEY) || 'de';
  }

  /* --- Feste Texte über SJ_PAIRS übersetzen --- */
  var PAIR_ATTRS = ['alt', 'title', 'aria-label', 'placeholder'];
  var pairMap = null;

  function norm(s) { return s.replace(/\s+/g, ' ').trim(); }

  function getPairMap() {
    if (pairMap) return pairMap;
    pairMap = {};
    (window.SJ_PAIRS || []).forEach(function (p) {
      pairMap[p[0]] = p;
      pairMap[p[1]] = p;
    });
    return pairMap;
  }

  function insideI18n(node) {
    for (var el = node.parentNode; el && el.nodeType === 1; el = el.parentNode) {
      if (el.hasAttribute('data-i18n') || el.tagName === 'SCRIPT' || el.tagName === 'STYLE') return true;
    }
    return false;
  }

  function applyPairs(idx) {
    var map = getPairMap();

    var walker = document.createTreeWalker(document.documentElement, NodeFilter.SHOW_TEXT);
    var node;
    while ((node = walker.nextNode())) {
      if (node.sjPair === undefined) {
        var key = norm(node.nodeValue);
        node.sjPair = (key && map[key] && !insideI18n(node)) ? map[key] : null;
      }
      if (node.sjPair) {
        var m = node.nodeValue.match(/^(\s*)[\s\S]*?(\s*)$/);
        node.nodeValue = m[1] + node.sjPair[idx] + m[2];
      }
    }

    document.querySelectorAll('[alt], [title], [aria-label], [placeholder]').forEach(function (el) {
      if (!el.sjPairs) {
        el.sjPairs = {};
        PAIR_ATTRS.forEach(function (a) {
          var v = el.getAttribute(a);
          if (v && map[norm(v)]) el.sjPairs[a] = map[norm(v)];
        });
      }
      Object.keys(el.sjPairs).forEach(function (a) {
        el.setAttribute(a, el.sjPairs[a][idx]);
      });
    });
  }

  function applyLang(lang) {
    var dict = window.SJ_LANG[lang];
    if (!dict) return;

    document.querySelectorAll('[data-i18n]').forEach(function (el) {
      var key = el.getAttribute('data-i18n');
      if (dict[key] !== undefined) {
        el.innerHTML = dict[key];
      }
    });

    applyPairs(lang === 'en' ? 1 : 0);

    /* Update skill-item hover labels */
    document.querySelectorAll('[data-level-de][data-level-en]').forEach(function (el) {
      el.setAttribute('data-level', el.getAttribute('data-level-' + lang));
    });

    /* Update toggle button label */
    var btn = document.getElementById('lang-toggle');
    if (btn) btn.textContent = lang === 'de' ? 'EN' : 'DE';

    /* Update html lang attribute */
    document.documentElement.lang = lang;
  }

  window.SJ_toggleLang = function () {
    var next = getCurrentLang() === 'de' ? 'en' : 'de';
    localStorage.setItem(STORAGE_KEY, next);
    applyLang(next);
  };

  /* Apply on load */
  document.addEventListener('DOMContentLoaded', function () {
    applyLang(getCurrentLang());
  });
})();
